		"大小写两个未知字段": `{"version":1,"foo":1,"Foo":2}`,
		"课程对象内未知字段大小写变体": `{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"open":true,"bar":1,"BAR":2}]}`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
