			`{"id":"c1","name":"数学","credit":4,"ope` + escapedN + `":null}]}` + "\n",
		"c1", "opeN",
	},
	"顶层COURSES变体里的null状态": {
		`{"version":1,"COURSES":[` +
			`{"id":"c1","name":"数学","credit":4,"open":null}]}` + "\n",
		"c1", "open",
	},
	"问题课程未被任何要求引用": {
		`{"version":1,"courses":[` +
			`{"id":"c9","name":"无关课程","credit":1,"open":null}],` +
			`"students":[{"id":"s1"}]}` + "\n",
