// 显式写成 null。wantKey 是错误信息应点名的字段原始写法（解码后文字）。
var nullOpenRejectCases = map[string]struct {
	content string
	course  string
	wantKey string
}{
	"小写open显式null": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"open":null}]}` + "\n",
		"c1", "open",
	},
	"首字母大写Open": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"Open":null}]}` + "\n",
		"c1", "Open",
	},
	"全大写OPEN": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"OPEN":null}]}` + "\n",
		"c1", "OPEN",
	},
	"状态字段在最前位置不影响": {
		`{"version":1,"courses":[` +
			`{"open":null,"id":"c1","name":"数学","credit":4}]}` + "\n",
		"c1", "open",
	},
	"编号出现在null之后仍点名课程": {
		`{"version":1,"courses":[` +
			`{"name":"数学","credit":4,"open":null,"id":"c1"}]}` + "\n",
		"c1", "open",
	},
	"unicode转义小写键": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"` + escapedOpenKeyLower + `":null}]}` + "\n",
		"c1", "open",
	},
	"unicode转义大写键": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"` + escapedOpenKeyUpper + `":null}]}` + "\n",
		"c1", "OPEN",
	},
	"部分转义混合大小写": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"ope` + escapedUpperN + `":null}]}` + "\n",
		"c1", "opeN",
	},
	"顶层COURSES变体里的null状态": {
		`{"version":1,"COURSES":[` +
			`{"id":"c1","name":"数学","credit":4,"open":null}]}` + "\n",
		"c1", "open",
	},
	"问题课程未被任何要求引用": {
		`{"version":1,"courses":[` +
			`{"id":"c9","name":"无关课程","credit":1,"open":null}],` +
			`"students":[{"id":"s1"}]}` + "\n",
		"c9", "open",
	},
	"多门课程中第二门状态为空": {
		`{"version":1,"courses":[` +
			`{"id":"c1","name":"数学","credit":4,"open":true},` +
			`{"id":"c2","name":"物理","credit":3,"Open":null}]}` + "\n",
		"c2", "Open",
	},
	"嵌套数组中的课程状态为空": {
		`{"version":1,"courses":[[` +
			`{"id":"c3","name":"化学","credit":2,"open":null}]]}` + "\n",
		"c3", "open",
	},
}

